import { PDFParse } from 'pdf-parse';

// Pulls the text layer out of a PDF locally — no AI, no network. Lab
// reports generated by lab software are digital PDFs whose text is right
// there in the file; reading it here takes about a second, versus minutes
// for an AI model to look at a multi-megabyte PDF as images. Scanned
// paper reports have no text layer and return '' (the caller then falls
// back to sending the file itself to the AI).

const PARSE_TIMEOUT_MS = 20_000;

export async function extractPdfText(data: Buffer): Promise<string> {
  const parser = new PDFParse({ data: new Uint8Array(data) });
  try {
    const result = await Promise.race([
      parser.getText(),
      new Promise<never>((_, reject) =>
        setTimeout(() => reject(new Error('PDF text extraction timed out')), PARSE_TIMEOUT_MS).unref(),
      ),
    ]);
    return result.text
      .replace(/^-- \d+ of \d+ --$/gm, '')
      .replace(/[ \t]+/g, ' ')
      .replace(/\n\s*\n+/g, '\n')
      .trim();
  } catch {
    return '';
  } finally {
    await parser.destroy().catch(() => undefined);
  }
}

// Enough real text (and numbers) to be a readable report rather than a
// scan with a stray header line.
export function looksLikeReportText(text: string): boolean {
  const digits = (text.match(/\d/g) ?? []).length;
  return text.length >= 200 && digits >= 20;
}
